    dt_latest = datetime.strptime(latest, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    delta = int((dt_latest - dt_earliest).total_seconds())

    print(f"{'first':<5} {earliest}")
    print(f"{'last':<5} {latest}")
    print(f"{'secs':<5} {delta}")

    return 0


def main(argv: list[str]) -> int:
    """Run the tool and return the process exit code."""
    if not argv:
        print("Usage: python3 logstat.py <subcommand> [options] [FILE]", file=sys.stderr)
        return 2

    result = parse_args(argv)
    subcommand, min_level, number, files = result

    if subcommand is None:
        print("Usage: python3 logstat.py <subcommand> [options] [FILE]", file=sys.stderr)
        return 2

    if len(files) > 1:
        print("Usage: python3 logstat.py <subcommand> [options] [FILE]", file=sys.stderr)
        return 2

