    if lines is None:
        print("Usage: python3 logstat.py <subcommand> [options] [FILE]", file=sys.stderr)
        return 3

    # Parse lines
    records: list[dict] = []
    line_num = 0
    for line in lines:
        line_num += 1
        if not line.strip():
            continue  # blank line, ignore

        record = parse_record(line, line_num)
        if record is None:
            print(f"logstat: malformed record on line {line_num}", file=sys.stderr)
            return 4

