    if min_level is not None:
        records = process_records(records, min_level)

    # Handle span zero records
    if subcommand == "span" and not records:
        print("logstat: no records matched", file=sys.stderr)
        return 5

    # Dispatch
    if subcommand == "count":
        return cmd_count(records, min_level or "DEBUG")
    elif subcommand == "top":
        if number is None:
            number = 3
        return cmd_top(records, min_level or "DEBUG", number)
    elif subcommand == "span":
        return cmd_span(records, min_level or "DEBUG")

    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
